  /**
   * First band shown.
   */
  uint8_t first_band;
  /**
   * Transform order in use.
   */
  uint8_t fft_order;
  /**
   * The device refused the last configuration.
   */
  bool config_rejected;
  /**
   * Seconds between frames.
   */
